package org.apache.commons.lang3.text.translate;

import java.io.*;
import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class NumericEntityUnescaper_translate_TriageGen4Test {

    private NumericEntityUnescaper unescaper;
    private StringWriter writer;

    @Before
    public void setUp() {
        unescaped = new NumericEntityUnescaper();
        writer = new StringWriter();
    }

    @Test
    public void testTranslate_NoMatch() throws IOException {
        CharSequence input = "abc";
        int result = unescaper.translate(input, 0, writer);
        assertEquals(0, result);
        assertEquals("", writer.toString());
    }

    @Test
    public void testTranslate_DecimalEntity() throws IOException {
        // &#123; -> {
        // index 0: '&', index 1: '#', start: 2, end: 5 (at ';')
        // isHex = false
        // entityValue = 123
        // return 2 + (5-2) + 0 + 1 = 6
        CharSequence input = "&#123;";
        int result = unescaper.translate(input, 0, writer);

        assertEquals(6, result);
        // Note: out.write(int) writes a single character with that code point
        assertEquals(String.valueOf((char) 123), writer.toString());
    }

    @Test
    public void testTranslate_HexEntityLower() throws IOException {
        // &#x7B; -> {
        // index 0: '&', index 1: '#', start: 2, isHex = true (start becomes 3), end: 5
        // entityValue = 7B (123)
        // return 2 + (5-3) + 1 + 1 = 6
        CharSequence input = "&#x7B;";
        int result = unescaper.translate(input, 0, writer);

        assertEquals(6, result);
        assertEquals(String.valueOf((char) 123), writer.toString());
    }

    @Test
    public void testTranslate_HexEntityUpper() throws IOException {
        // &#X7B;
        CharSequence input = "&#X7B;";
        int result = unescaper.translate(input, 0, writer);

        assertEquals(6, result);
        assertEquals(String.valueOf((char) 123), writer.toString());
    }

    @Test
    public void testTranslate_NumberFormatExceptionDecimal() throws IOException {
        // &#abc; -> Not a decimal number
        CharSequence input = "&#abc;";
        int result = unescaper.translate(input, 0, writer);

        assertEquals(0, result);
        assertEquals("", writer.toString());
    }

    @Test
    public void testTranslate_NumberFormatExceptionHex() throws IOException {
        // &#xG1; -> Not a hex number
        CharSequence input = "&#xG1;";
        int result = unescaper.translate(input, 0, writer);

        assertEquals(0, result);
        assertEquals("", writer.toString());
    }

    @Test(expected = IndexOutOfBoundsException.class)
    public void testTranslate_IndexOutOfBounds_End() throws IOException {
        // Accessing input.charAt(index + 1) where index is last char
        CharSequence input = "&";
        unescaped.translate(input, 0, writer);
    }

    @Test(expected = IndexOutOfBoundsException.class)
    public void testTranslate_IndexOutOfBounds_NoSemicolon() throws IOException {
        // While loop will run out of bounds
        CharSequence input = "&#123";
        unescaped.translate(input, 0, writer);
    }

    @Test(expected = IndexOutOfBoundsException.class)
    public void testTranslate_IndexOutOfBounds_EmptyInput() throws IOException {
        CharSequence input = "";
        unescaped.translate(input, 0, writer);
    }
}
